    "boldQuestion": "ما هو الهدي النبوي والمنهج السلوكي للتعافي من وساوس التشكيك وإعادة الوضوء والصلاة؟",
    "colorAccent": "violet",
    "badgeText": "تزكية وصحة نفسية #580",
    "theDilemma": "يقع الموسوس في شباك التكرار المنهك للوضوء والصلاة والشك في صحة الإيمان، مما يقوده لليأس والعنت، والشارع حسم هذه المعاناة بقواعد فقهية صارمة تأمر بقطع الشك والبناء على اليقين وتجاهل الخواطر.",
    "rationalDeconstruction": [
      "١. كراهة العبد للوسوسة دليل على صريح إيمانه: فزع الصحابة من خواطر الشك طمأنهم النبي ﷺ بأن ذلك محض الإيمان.",
      "٢. القاعدة الفقهية الكبرى (اليقين لا يزول بالشك): البناء على الطهارة وصحة الصلاة ما لم يحصل يقين قطعي حسي.",
      "٣. العلاج بالتعريض ومنع الاستجابة (ERP): تجاهل الوسواس تماماً وعدم إعادة الفعل هو الدواء الفقهي والسلوكي الحاسم.",
      "٤. الاستعاذة والاشتغال بالنافع: قطع الاسترسال مع الفكرة الوسواسية واللجوء الفوري للذكر والعمل الصالح."
    ],
    "scripturalFoundations": [
      {
        "text": "«جَاءَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ أَحَدَنَا لَيَجِدُ فِي نَفْسِهِ الشَّيْءَ لَأَنْ يَكُونَ حُمَمَةً أَحَبُّ إِلَيْهِ مِنْ أَنْ يَتَكَلَّمَ بِهِ، فَقَالَ: اللَّهُ أَكْبَرُ! الْحَمْدُ لِلَّهِ الَّذِي رَدَّ كَيْدَهُ إِلَى الْوَسْوَسَةِ»",
        "source": "سنن أبي داود: 5112",
        "pointOfEvidence": "البلسم النبوي المطمئن لمن يعاني من خواطر الوسواس بأنها لا تضره طالما كرهها ولم يتكلم بها."
      }
    ],
    "decisiveRule": "«الموسوس يُمنع من إعادة العبادة، واليقين لا يرتفع بأوهام الشكوك، وتجاهل الوسواس واجب».",
    "practicalTakeaway": "الراحة التامة واليقين برحمة الله وتيسير الشريعة، والامتناع القطعي عن تكرار الوضوء والصلاة استجابة للشيطان.",
