      "٢. الصدق في التوبة وإزالة المثيرات: غلق النوافذ الرقمية وبرامج الحماية وقطع الخلوات المشبوهة فوراً.",
      "٣. ملء الفراغ بالبدائل الإيجابية: الرياضة، القراءة، بناء العلاقات الاجتماعية الحقيقية، والاجتهاد في العبادة.",
