      "٣. مشروعية الدواء النفسي: استشارة الأطباء وتناول الأدوية النفسية من الأخذ بالأسباب المشروعة التي أمر بها الشارع.",
      "٤. تكامل العلاج الطبي والروحي: الجمع بين الطب النفسي المتخصص والسكينة الإيمانية بالذكر والدعاء يعجل بالشفاء."
